# owner: platform
"""Absence notices for parents."""

from typing import Iterable

from rosterkit.attendance import days_missed
from rosterkit.errors import ProjectError
from rosterkit.models import Mark, Student

def _check(student: Student, marks: list) -> list:
    own = student.student_id
    if any(m.student_id != own for m in marks):
        raise ProjectError("marks for another student")
    return days_missed(marks)

# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Short text notice of a student's absent days."""
    days = _check(student, list(marks))
    if not days:
        raise ProjectError("no absences to report")
    return _compose(student, days)

def _compose(student: Student, days) -> str:
    name = f"{student.first_name} {student.last_name}"
    dates = ", ".join(d.isoformat() for d in days)
    return (
        f"{name} missed {len(days)} day(s): "
        f"{dates}"
    )
